import sqlite3
S='/tmp/claude-0/-home-user-guidebook/f366a537-569c-50d0-a2d1-f74dc994928a/scratchpad/antagonist'
a=sqlite3.connect(f'file:{S}/rebuilt.db?mode=ro',uri=True)
