print('schema only in rebuilt:', sorted(x[:2] for x in sa-sb)); print('schema only in merged:', sorted(x[:2] for x in sb-sa))
def rows(c,t):
    cols=[r[1] for r in c.execute(f'pragma table_info("{t}")')]
    return cols, sorted(map(repr, c.execute(f'select {",".join(chr(34)+x+chr(34) for x in cols)} from "{t}"')))
diffs=[]
for (t,) in a.execute("select name from sqlite_master where type='table'"):
    ca,ra=rows(a,t); cb,rb=rows(b,t)
    if ca!=cb or ra!=rb: diffs.append((t,len(ra),len(rb),len(set(ra)-set(rb)),len(set(rb)-set(ra))))
print('row diffs (table, n_rebuilt, n_merged, only_rebuilt, only_merged):', diffs)
print('views referencing observed_terms:', [r[0] for r in b.execute("select name from sqlite_master where type='view' and sql like '%observed_terms%'")])
print('views referencing terms.catalogue:', [r[0] for r in b.execute("select name from sqlite_master where type='view' and sql like '%catalogue%'")])
PY

